window.FILM_WORK_PROMPTS={"work_id":"src-7e250fa9cac8d101","records":[{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-d8235f63d2e17490","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1152).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"金发人物面部占据画面主体，手持细长红色物体垂直置于脸前，背景为模糊的暗绿色调，人物神情平静，视线略微向下。","analysis":"画面采用极近距离构图，人物面部占据绝大部分空间，仅可见头部及手部局部。视线平视，光线柔和均匀，无明显阴影。色彩以冷调的暗绿背景与人物苍白的肤色、金发形成对比，红色物体在画面中形成强烈的视觉焦点。","prompt":"极近距离的人物面部特写，金发年轻女性，皮肤白皙，蓝色眼睛，神情平静且略带忧郁，视线向下。她手持一根细长的红色物体，垂直放置在面部前方，从额头延伸至脸颊。背景为模糊的暗绿色调，光线柔和，色彩冷峻，红色物体与冷色背景形成鲜明对比，画面具有电影质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:35:38-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1152).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.515,"observed_resolution":"normal","observation_limits":[],"id":"VP-947f49d6dc1f7c20","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-cab167cf429f3d90","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1176).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"金发人物站立在斑驳的绿色车厢外，身穿深色花纹上衣，系着浅色领巾，低头整理衣物，背景是带有锈迹和窗户的车厢壁。","analysis":"画面采用横向构图，人物位于右侧三分之一处，仅上半身可见。左侧大面积留白给车厢结构，包括一个圆角矩形小窗和两扇较大的矩形窗户。光线从右上方投射，在人物面部和车厢表面形成明暗对比，色调偏冷绿，带有复古胶片质感。","prompt":"一位金发人物站立在老旧的绿色车厢旁，身穿深色花纹长袖上衣，颈部系着一条浅黄色领巾，双手在胸前整理衣物。人物位于画面右侧，仅上半身入镜。背景是占据画面大部分面积的绿色金属车厢壁，表面布满锈迹和污渍，左侧有一个圆角矩形小窗，中间偏右有两扇并排的矩形窗户，窗玻璃反光模糊。阳光从右上方照射，在人物和车厢上投下清晰的阴影，整体色调呈现复古的冷绿色，具有胶片颗粒感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:35:45-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1176).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.524,"observed_resolution":"normal","observation_limits":[],"id":"VP-0bc35c9930d21318","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-957f55ef56899e45","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1173).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"昏暗环境中，一只动物面部占据画面右侧，眼睛反射出微弱光点，左侧大面积黑暗，左上角有模糊绿色线条。","analysis":"画面主体为动物面部局部，仅可见眼部及周围皮毛，身体其余部分不可见。构图极度偏右，左侧约三分之一为纯黑区域。光线极暗，仅眼部有微弱反光，整体色调呈深褐与黑色，噪点明显，营造出压抑、神秘的视觉氛围。","prompt":"极度昏暗的夜间画面，右侧占据大部分画幅的是一只动物面部特写，皮毛呈深褐色，质感粗糙，一只眼睛在黑暗中反射出微弱的黄白色光点，眼神深邃。画面左侧约三分之一区域完全隐没在浓重的黑色阴影中，左上角隐约可见一条模糊的绿色斜向线条。整体光线极弱，噪点明显，色调阴冷压抑，仅靠眼部反光和皮毛微弱轮廓维持视觉焦点，营造出一种神秘且紧张的窥视感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:35:52-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1173).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.498,"observed_resolution":"normal","observation_limits":[],"id":"VP-b2980189bb3e6ad1","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-2bcccab7b6838034","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1149).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"画面主体为一张极度贴近的人脸眼部区域，双眼直视前方，面部皮肤带有明显的黑色污迹与红色痕迹，背景完全隐没于黑暗之中。","analysis":"构图极度紧凑，仅呈现人物双眼及鼻梁上部的面部特写，环境占比几乎为零。视线平视，双眼占据画面核心位置。光线昏暗，整体色调偏冷，眼部周围有银灰色眼影，眼白处可见红色血丝，脸颊分布着黑色污渍，明暗对比强烈，营造出阴冷压抑的视觉氛围。","prompt":"极度贴近的人脸眼部特写，双眼直视镜头，瞳孔呈蓝绿色。眼部周围涂抹着厚重的银灰色眼影，眼线深邃，眼白处带有明显的红色血丝。面部皮肤质感真实，脸颊及眼角下方分布着不规则的黑色污迹与擦痕，鼻梁处有微弱的高光反射。整体光线昏暗，色调偏冷，背景完全隐没于黑暗之中，画面聚焦于双眼的凝视感与面部的脏污细节，呈现出一种阴冷、压抑且充满张力的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:35:59-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1149).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.536,"observed_resolution":"normal","observation_limits":[],"id":"VP-9a50470b8012bc96","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-1fe23b55608fc9eb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1052).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"深暗水下，一名人物身体呈水平姿态悬浮于画面右侧，上方水面波光粼粼，左侧大面积为黑色水域。","analysis":"画面采用侧视构图，人物位于右侧，身体轮廓在逆光下清晰可见，呈流线型。上方水面占据约三分之一画面，光线从上方穿透，形成强烈的明暗对比。人物身体大部分处于阴影中，仅边缘被照亮，呈现出冷调的蓝绿色光感，营造出深邃、静谧且略带压抑的视觉氛围。","prompt":"这是一张深暗水下的摄影作品，画面主体为一名悬浮的人物，位于画面右侧，身体呈水平姿态。人物身体轮廓在逆光下清晰可见，呈流线型，四肢舒展。上方水面波光粼粼，光线从上方穿透，形成强烈的明暗对比。人物身体大部分处于阴影中，仅边缘被照亮，呈现出冷调的蓝绿色光感。左侧大面积为黑色水域，营造出深邃、静谧且略带压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:36:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (1052).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.384,"observed_resolution":"normal","observation_limits":[],"id":"VP-e26443e7e2bd2f70","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-a8e1b60f062795db","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1152).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"舞台中央站立的人物背影，身穿金色亮片上衣与红色长裤，手持麦克风。背景为昏暗的观众席，舞台边缘排列着彩色圆形灯光，顶部强光照射。","analysis":"人物位于画面正中，全身可见，呈站立姿态。构图采用中心对称，人物占据画面约三分之一高度。顶部强逆光形成光晕，使人物面部不可见，仅见轮廓。舞台前沿的彩色灯光（红、黄、绿、白）形成水平亮带，与上方冷色调光束形成对比。背景观众席处于阴影中，仅见模糊人影。","prompt":"舞台中央站立的人物背影，身穿金色亮片长袖上衣与红色长裤，右手持麦克风。人物全身可见，位于画面正中。顶部强逆光照射，形成明显光晕，人物面部处于阴影中。舞台前沿排列着红、黄、绿、白四色圆形灯光，形成水平亮带。背景为昏暗的观众席，可见模糊的观众人影。整体色调偏冷，顶部光束呈青蓝色，舞台灯光色彩鲜艳。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:48:31+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (1152).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.562,"observed_resolution":"normal","observation_limits":[],"id":"VP-62da9b2e6fdd8889","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-1cdf4a6d4a2332e5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1176).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"夜色中，巨大的灰白色板状结构占据画面上方，下方黑暗处站立着三个人影，周围是杂草丛生的荒地。","analysis":"构图上，巨大的板状结构从上方压下来，占据画面约70%的面积，形成强烈的压迫感。下方三个人物全身可见，但相对巨大背景显得极小。视角略微仰视，强调了背景的高大。光线昏暗，主要光源似乎来自前方或上方，照亮了人物和部分背景板，背景板呈现灰白色调，带有斑驳的纹理，而周围环境则陷入深黑色。","prompt":"这是一张夜间户外场景的静帧。画面上方被巨大的、由灰白色矩形板块拼接而成的结构占据，板块表面有斑驳的污渍和纹理，结构下方有支撑架。在结构下方的黑暗地面上，站立着三个人物，他们全身可见，身形在巨大的背景衬托下显得渺小。左侧人物穿着红色上衣，中间和右侧人物穿着深色衣物。人物周围是杂草丛生的荒地，植被在夜色中呈现暗绿色和枯黄色。整体光线昏暗，主要光源照亮了人物和背景结构的一部分，营造出一种压抑、神秘的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:48:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (1176).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.504,"observed_resolution":"normal","observation_limits":[],"id":"VP-d2850417a67beb6c","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-f606320a1aca6b24","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1173).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"黑色背景中散布着大量微小的红色光点，中央区域聚集着数个较大的彩色球体，包括黄色、青色、粉色和紫色，球体表面附着着更小的深色圆点，呈现出微观或抽象的视觉效果。","analysis":"画面采用中心构图，彩色球体主要集中在画面中部，周围被密集的微小光点包围。球体大小不一，前景的球体较大且清晰，背景逐渐模糊。光线似乎从球体内部发出，形成自发光效果，色彩饱和度高，与深色背景形成强烈对比，营造出一种神秘且梦幻的氛围。","prompt":"这是一幅微观或抽象风格的画面，背景为深黑色，布满了无数细小的红色光点，如同星空或细胞结构。画面中央漂浮着几个较大的发光球体，颜色各异，包括明亮的黄色、清新的青色、鲜艳的粉色和神秘的紫色。这些球体表面并不光滑，而是附着着许多更小的深色圆点，仿佛气泡或细胞核。球体之间保持着一定的距离，错落有致地分布在空间中。光线柔和而均匀，没有明显的阴影，色彩在黑暗中显得格外耀眼，整体画面给人一种静谧、深邃且充满生命力的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:49:00+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (1173).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.6,"observed_resolution":"normal","observation_limits":[],"id":"VP-43bd16b19457350e","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-da294dd6d9490e65","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (1142).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"金发人物从红白方格纹理的垂直隔断后探出半张脸，背景为同色系的密集方格墙面，人物肩部可见红色樱桃图案，整体色调偏冷暗。","analysis":"画面采用左右分割构图，右侧大面积被红白方格纹理的垂直平面遮挡，左侧露出人物面部及左肩。人物头部微侧，眼神直视镜头，眼部有蓝绿色眼影，嘴唇微张。光线昏暗柔和，色彩以暗红、灰白和冷调肤色为主，方格纹理在画面中占据约70%面积，形成强烈的几何重复感。","prompt":"金发人物从红白方格纹理的垂直隔断后探出半张脸，面部位于画面左侧三分之一处，眼神直视镜头，眼部涂有蓝绿色眼影，嘴唇微张，左肩可见红色樱桃图案。右侧约三分之二画面被红白方格纹理的垂直平面遮挡，背景为同色系的密集方格墙面。整体色调偏冷暗，光线昏暗柔和，方格纹理形成强烈的几何重复感，人物肤色在暗调环境中显得苍白，营造出窥视与压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:49:20+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (1142).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.546,"observed_resolution":"normal","observation_limits":[],"id":"VP-144e68959fea1f8c","origin":"visual"},{"work_id":"src-7e250fa9cac8d101","frame_id":"FG-168be03ff729482c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (1039).jpg","source_page":"https://film-grab.com/2016/05/23/the-runaways/","scene":"两名身穿浅色衣物的人物并排坐在户外木质野餐桌旁，背景是红砖建筑与绿色金属雨棚，前景为大片枯黄草地。","analysis":"画面采用远景构图，人物位于左侧三分之一处，全身可见但面部细节模糊。背景红砖墙占据画面上半部，绿色雨棚横跨画面，形成水平线条。光线为自然日光，色调偏暖黄与红褐，草地呈现枯黄质感，整体氛围静谧。","prompt":"远景镜头，户外场景。两名身穿浅粉色或米色宽松衣物的人物并排坐在木质野餐桌的长凳上，身体微微前倾，姿态亲密。背景是一栋多层红砖建筑，窗户排列整齐，建筑前方延伸出绿色的金属结构雨棚。前景是大片枯黄的草地，野餐桌位于画面左侧。自然光照明，色彩呈现复古的暖色调，红砖与绿棚形成对比，画面具有胶片质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:49:32+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (1039).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-77f12155fadda842","origin":"visual"}]};